// Packages: Azure.Security.KeyVault.Secrets, Azure.Identity
// Install: dotnet add package Azure.Security.KeyVault.Secrets
//         dotnet add package Azure.Identity

using Azure.Identity;
using Azure.Security.KeyVault.Secrets;

public class ManagedIdentitySecretService
{
    private readonly SecretClient _client;

    public ManagedIdentitySecretService(string keyVaultUri)
    {
        // DefaultAzureCredential uses managed identity in Azure, AzureCliCredential locally
        var credential = new DefaultAzureCredential();
        _client = new SecretClient(new Uri(keyVaultUri), credential);
    }

    public async Task<string> GetConnectionStringAsync(string secretName, CancellationToken ct = default)
    {
        try
        {
            KeyVaultSecret secret = await _client.GetSecretAsync(secretName, ct);
            Console.WriteLine($"Secret '{secretName}' retrieved via managed identity");
            return secret.Value;
        }
        catch (AuthenticationFailedException ex)
        {
            Console.WriteLine($"Managed identity auth failed: {ex.Message}");
            throw;
        }
        catch (RequestFailedException ex)
        {
            Console.WriteLine($"Key Vault access failed: {ex.Message}");
            throw;
        }
    }
}

// Usage - no connection string or client secret required
var service = new ManagedIdentitySecretService("https://aspnet-azure-kv.vault.azure.net/");
string connectionString = await service.GetConnectionStringAsync("ConnectionStrings--Default");

// Expected output (in Azure with managed identity enabled):
// Secret 'ConnectionStrings--Default' retrieved via managed identity
